"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9016"],{99481(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_invalida","status":422,"titulo":"A resolu\xe7\xe3o de Pesos por \xc1rea excede o tamanho permitido ou cont\xe9m caractere de controle, de formata\xe7\xe3o ou de quebra de linha"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_invalida","requisitos":[],"oQueAconteceu":["Na classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local pela m\xe9dia ponderada, o texto de\\n`resolucaoPesoAreaEnem` tem mais de 40 caracteres (limite de hoje, sem contar os espa\xe7os nas\\npontas) ou cont\xe9m caractere de controle, de formata\xe7\xe3o, de quebra de linha ou que n\xe3o seja\\ntexto. A resolu\xe7\xe3o aparece em mensagens de recusa e em registros do sistema, e por isso a\\nforma dela \xe9 conferida antes de qualquer consulta ao cadastro.","A recusa vem no campo `resolucaoPesoAreaEnem` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es da classifica\xe7\xe3o. Com a forma inv\xe1lida, o cadastro de Pesos por \xc1rea n\xe3o \xe9\\nconsultado: as recusas de a resolu\xe7\xe3o n\xe3o ter pesos\\n([`resolucao_peso_area_enem_nao_encontrada`](/erros/uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_nao_encontrada))\\nou de t\xea-los incompletos\\n([`resolucao_peso_area_enem_incompleta`](/erros/uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_incompleta))\\ns\xf3 aparecem depois que a forma for corrigida.","Esta confer\xeancia tamb\xe9m ocorre na leitura da configura\xe7\xe3o publicada, nas opera\xe7\xf5es indicadas no cabe\xe7alho da p\xe1gina. Nesses casos, a recusa se refere \xe0 vers\xe3o publicada, sai sem a lista `errors[]` e n\xe3o se refere ao pedido enviado. A consulta de conformidade registra uma pend\xeancia no lugar deste erro. Na leitura, texto com mais de 40 caracteres, n\xe3o-caractere (como U+FFFE) ou surrogate sem par recebe antes [`envelope_malformado`](/erros/uniplus.selecao.envelope_codec.envelope_malformado); esta causa cobre caracteres de controle, formata\xe7\xe3o ou quebra de linha."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, informe a resolu\xe7\xe3o exatamente como est\xe1 cadastrada em Pesos\\npor \xc1rea (Configura\xe7\xe3o), com no m\xe1ximo 40 caracteres, em uma s\xf3 linha e sem caracteres\\ninvis\xedveis. O mais seguro \xe9 copiar o texto do cadastro.","Se o erro apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas\\nno cabe\xe7alho, exceto a defini\xe7\xe3o da classifica\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);